-- Database setup, generated by scripts/copy-setup-sql.sh on 2026-11-27. Safe to run again.

-- >>> 20261127000029_companies.sql (skipped automatically if already applied)
do $guard$ begin
  if to_regclass('public.companies') is null then
    execute $setup_20261127000029_companies$
-- =============================================================================================
-- Companies (player groups), delivery 1 (owner decisions 2026-11-27, docs/COMPANIES_PLAN.md):
--   * a Company: name, motto, city or online, languages, games (free text), description, crest
--     (built-in generator, stored as small numbers), public or private, joining modes (invitation,
--     link / QR code, open), member limit (default 50; the leader lowers it, an admin raises the ceiling),
--     opt-in to challenges and rankings (used by later deliveries).
--   * any signed-in player creates one, no validation; reports afterwards (3 reporters hide it).
--   * roles: leader, officers, members, recruits. New arrivals are recruits. Officers invite, remove
--     members and recruits, moderate the chat, manage events and edit the card; the leader also
--     changes the settings, names officers, hands over and dissolves.
--   * several Companies per player (10 at most), one main Company shown on the profile.
--   * the leader leaves or deletes their account: the oldest officer takes over, else the oldest
--     member; an empty Company is dissolved.
--   * realtime chat for members, announcements (pinned messages, officers) notified to members.
--     Messages stay when their author deletes their account, under "Deleted player".
--   * calendar: events for members (date, place, details), who comes (yes / maybe / no).
-- All writes go through the functions below; tables only get read policies.
-- =============================================================================================

create type public.company_role as enum ('leader', 'officer', 'member', 'recruit');

create table public.companies (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  name          text not null check (char_length(btrim(name)) between 2 and 60),
  motto         text not null default '' check (char_length(motto) <= 120),
  description   text not null default '' check (char_length(description) <= 1000),
  city          text check (city is null or char_length(city) <= 80),
  country       text check (country is null or country ~ '^[A-Z]{2}$'),
  is_online     boolean not null default false,
  languages     text[] not null default '{}',
  games         text not null default '' check (char_length(games) <= 200),
  crest         jsonb not null default '{}',
  is_public     boolean not null default true,
  join_open     boolean not null default false,
  join_invite   boolean not null default true,
  join_link     boolean not null default true,
  member_limit  int not null default 50 check (member_limit between 2 and 1000),
  limit_ceiling int not null default 50 check (limit_ceiling between 2 and 1000),
  competitive   boolean not null default true,
  is_hidden     boolean not null default false,
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  check (member_limit <= limit_ceiling)
);
create index companies_created_by_idx on public.companies (created_by, created_at);

create table public.company_members (
  company_id uuid not null references public.companies (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  role       public.company_role not null default 'recruit',
  is_main    boolean not null default false,
  joined_at  timestamptz not null default now(),
  primary key (company_id, user_id)
);
create index company_members_user_idx on public.company_members (user_id);
create unique index company_members_one_leader on public.company_members (company_id) where role = 'leader';
create unique index company_members_one_main on public.company_members (user_id) where is_main;

-- Invitation link: officers only can read the token.
create table public.company_links (
  company_id uuid primary key references public.companies (id) on delete cascade,
  token      text not null unique,
  expires_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.company_invites (
  id         uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  invited_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  unique (company_id, user_id)
);
create index company_invites_user_idx on public.company_invites (user_id);

create table public.company_messages (
  id           uuid primary key default gen_random_uuid(),
  company_id   uuid not null references public.companies (id) on delete cascade,
  sender_id    uuid not null references public.profiles (id) on delete cascade,
  body         text not null check (char_length(btrim(body)) between 1 and 1000),
  is_announcement boolean not null default false,
  is_hidden    boolean not null default false,
  created_at   timestamptz not null default now()
);
create index company_messages_company_idx on public.company_messages (company_id, created_at);
create index company_messages_sender_idx on public.company_messages (sender_id, created_at);

create table public.company_events (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references public.companies (id) on delete cascade,
  title       text not null check (char_length(btrim(title)) between 2 and 120),
  starts_at   timestamptz not null,
  ends_at     timestamptz not null,
  place       text not null default '' check (char_length(place) <= 200),
  details     text not null default '' check (char_length(details) <= 1000),
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  check (ends_at > starts_at and ends_at <= starts_at + interval '7 days')
);
create index company_events_company_idx on public.company_events (company_id, starts_at);

create table public.company_event_answers (
  event_id uuid not null references public.company_events (id) on delete cascade,
  user_id  uuid not null references public.profiles (id) on delete cascade,
  answer   text not null check (answer in ('yes', 'maybe', 'no')),
  primary key (event_id, user_id)
);

-- ---------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------
create or replace function public.company_role_of(p_company uuid, p_user uuid default auth.uid())
returns public.company_role
language sql
stable
security definer
set search_path = public
as $$
  select role from public.company_members where company_id = p_company and user_id = p_user;
$$;

create or replace function public.is_company_member(p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.company_members where company_id = p_company and user_id = auth.uid());
$$;

create or replace function public.is_company_officer(p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.company_members where company_id = p_company and user_id = auth.uid() and role in ('leader', 'officer'));
$$;

-- The card (name, crest, city, games) is visible unless hidden by moderation.
create or replace function public.company_is_listed(p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.companies where id = p_company and not is_hidden)
      or public.is_company_member(p_company)
      or public.is_admin();
$$;

-- Members and record: public Company, its members, or an admin.
create or replace function public.company_content_visible(p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.companies where id = p_company and is_public and not is_hidden)
      or public.is_company_member(p_company)
      or public.is_admin();
$$;

revoke execute on function public.company_role_of(uuid, uuid), public.is_company_member(uuid), public.is_company_officer(uuid),
  public.company_is_listed(uuid), public.company_content_visible(uuid) from public;
grant execute on function public.company_role_of(uuid, uuid), public.is_company_member(uuid), public.is_company_officer(uuid),
  public.company_is_listed(uuid), public.company_content_visible(uuid) to anon, authenticated;

-- Crest: shape, division, pattern, symbol and three ink indexes, clamped to the generator's ranges.
create or replace function public.company_clean_crest(p jsonb)
returns jsonb
language plpgsql
immutable
set search_path = public
as $$
declare
  n int;
  pick int[];
  v jsonb;
  out jsonb := '{}';
  ranges constant jsonb := '{"shape": 5, "division": 5, "pattern": 5, "symbol": 11}';
  k text;
begin
  for k in select jsonb_object_keys(ranges) loop
    v := coalesce(p, '{}') -> k;
    n := case when jsonb_typeof(v) = 'number' then least(greatest(floor((v #>> '{}')::numeric)::int, 0), (ranges ->> k)::int) else 0 end;
    out := out || jsonb_build_object(k, n);
  end loop;
  pick := array[0, 1, 2];
  if jsonb_typeof(p -> 'inks') = 'array' then
    for n in 0 .. 2 loop
      v := p -> 'inks' -> n;
      if jsonb_typeof(v) = 'number' then
        pick[n + 1] := least(greatest(floor((v #>> '{}')::numeric)::int, 0), 5);
      end if;
    end loop;
  end if;
  return out || jsonb_build_object('inks', to_jsonb(pick));
end;
$$;

create or replace function public.company_clean_langs(p text[])
returns text[]
language sql
immutable
as $$
  select coalesce(array_agg(distinct l order by l), '{}')
    from unnest(coalesce(p, '{}')) l
   where l in ('en', 'ja', 'fr', 'es', 'de', 'it', 'pt', 'zh', 'ko');
$$;

-- Slug from the name (Latin letters and digits), a short random tail when taken or empty.
create or replace function public.company_make_slug(p_name text)
returns text
language plpgsql
volatile
set search_path = public
as $$
declare
  base text := left(btrim(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g'), '-'), 30);
  s text;
begin
  if char_length(base) < 2 then
    base := 'company';
  end if;
  s := base;
  while exists (select 1 from public.companies where slug = s) loop
    s := base || '-' || substr(md5(gen_random_uuid()::text), 1, 5);
  end loop;
  return s;
end;
$$;

-- Joins a player (checks the limit and the 10 Companies cap). Main Company when they have none.
create or replace function public.company_add_member(p_company uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.companies;
begin
  select * into c from public.companies where id = p_company for update;
  if not found then
    raise exception 'no_company';
  end if;
  if exists (select 1 from public.company_members where company_id = p_company and user_id = p_user) then
    raise exception 'already_member';
  end if;
  if public.is_suspended(p_user) then
    raise exception 'suspended';
  end if;
  if (select count(*) from public.company_members where company_id = p_company) >= c.member_limit then
    raise exception 'company_full';
  end if;
  if (select count(*) from public.company_members where user_id = p_user) >= 10 then
    raise exception 'too_many_companies';
  end if;
  insert into public.company_members (company_id, user_id, role, is_main)
  values (p_company, p_user, 'recruit', not exists (select 1 from public.company_members where user_id = p_user and is_main));
  delete from public.company_invites where company_id = p_company and user_id = p_user;
end;
$$;

-- Removes a player; a leaving leader hands over to the oldest officer, else the oldest member;
-- an empty Company is dissolved. The main flag moves to the player's oldest other Company.
create or replace function public.company_drop_member(p_company uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  m public.company_members;
  heir uuid;
  cname text;
  cslug text;
begin
  select * into m from public.company_members where company_id = p_company and user_id = p_user for update;
  if not found then
    raise exception 'not_member';
  end if;
  delete from public.company_members where company_id = p_company and user_id = p_user;
  delete from public.company_event_answers a using public.company_events e
   where e.id = a.event_id and e.company_id = p_company and a.user_id = p_user and e.starts_at > now();
  if m.is_main then
    update public.company_members set is_main = true
     where (company_id, user_id) = (select company_id, user_id from public.company_members where user_id = p_user order by joined_at limit 1);
  end if;
  if m.role = 'leader' then
    select user_id into heir from public.company_members
     where company_id = p_company
     order by (role = 'officer') desc, joined_at, user_id
     limit 1;
    if heir is null then
      delete from public.companies where id = p_company;
    else
      update public.company_members set role = 'leader' where company_id = p_company and user_id = heir;
      select name, slug into cname, cslug from public.companies where id = p_company;
      perform public.notify(heir, 'company_leader', jsonb_build_object('company', cname, 'company_slug', cslug));
    end if;
  end if;
end;
$$;

revoke execute on function public.company_clean_crest(jsonb), public.company_clean_langs(text[]), public.company_make_slug(text),
  public.company_add_member(uuid, uuid), public.company_drop_member(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Read policies
-- ---------------------------------------------------------------------------------------------
alter table public.companies enable row level security;
alter table public.company_members enable row level security;
alter table public.company_links enable row level security;
alter table public.company_invites enable row level security;
alter table public.company_messages enable row level security;
alter table public.company_events enable row level security;
alter table public.company_event_answers enable row level security;
revoke insert, update, delete on public.companies, public.company_members, public.company_links, public.company_invites,
  public.company_messages, public.company_events, public.company_event_answers from anon, authenticated;

create policy "listed companies" on public.companies for select using (public.company_is_listed(id));
create policy "members of visible companies" on public.company_members for select using (public.company_content_visible(company_id));
create policy "officers read the link" on public.company_links for select using (public.is_company_officer(company_id));
create policy "invites: invitee and officers" on public.company_invites for select
  using (user_id = auth.uid() or public.is_company_officer(company_id));
create policy "members read the chat" on public.company_messages for select
  using (public.is_company_member(company_id)
         and (not is_hidden or sender_id = auth.uid() or public.is_company_officer(company_id)));
create policy "admins read the chat" on public.company_messages for select using (public.is_admin());
create policy "members read the calendar" on public.company_events for select using (public.is_company_member(company_id) or public.is_admin());
create policy "members read the answers" on public.company_event_answers for select
  using (exists (select 1 from public.company_events e where e.id = event_id and public.is_company_member(e.company_id)));

create trigger companies_block_suspended before insert on public.companies for each row execute function public.block_suspended('created_by');
create trigger company_messages_block_suspended before insert on public.company_messages for each row execute function public.block_suspended('sender_id');

-- Realtime: new chat messages are pushed to members (RLS applies).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.company_messages;
  end if;
end $$;

alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in (
  'join_request', 'join_answer', 'game_match', 'report_to_confirm', 'report_answer', 'message',
  'game_message', 'league_game', 'round_paired', 'match_to_confirm', 'match_answer', 'contest_results',
  'round_schedule', 'mentor_request', 'mentor_answer', 'game_deleted', 'suggestion',
  'game_finished', 'game_comment',
  'company_invite', 'company_role', 'company_leader', 'company_event', 'company_announcement', 'company_removed', 'company_dissolved'));

alter type public.report_target add value if not exists 'company';
alter type public.report_target add value if not exists 'company_message';

-- ---------------------------------------------------------------------------------------------
-- Company card and settings
-- ---------------------------------------------------------------------------------------------
create or replace function public.create_company(p jsonb)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  new_id uuid;
  s text;
  nm text := btrim(coalesce(p ->> 'name', ''));
begin
  if me is null then
    raise exception 'not_authenticated';
  end if;
  if char_length(nm) not between 2 and 60 then
    raise exception 'bad_name';
  end if;
  if (select count(*) from public.companies where created_by = me and created_at > now() - interval '1 day') >= 3 then
    raise exception 'rate_limited';
  end if;
  if (select count(*) from public.company_members where user_id = me) >= 10 then
    raise exception 'too_many_companies';
  end if;
  s := public.company_make_slug(nm);
  insert into public.companies (slug, name, motto, description, city, country, is_online, languages, games, crest,
                                is_public, join_open, join_invite, join_link, created_by)
  values (s, nm,
          left(btrim(coalesce(p ->> 'motto', '')), 120),
          left(btrim(coalesce(p ->> 'description', '')), 1000),
          nullif(left(btrim(coalesce(p ->> 'city', '')), 80), ''),
          case when coalesce(p ->> 'country', '') ~ '^[A-Z]{2}$' then p ->> 'country' end,
          coalesce((p ->> 'is_online')::boolean, false),
          public.company_clean_langs(array(select jsonb_array_elements_text(case when jsonb_typeof(p -> 'languages') = 'array' then p -> 'languages' else '[]' end))),
          left(btrim(coalesce(p ->> 'games', '')), 200),
          public.company_clean_crest(p -> 'crest'),
          coalesce((p ->> 'is_public')::boolean, true),
          coalesce((p ->> 'join_open')::boolean, false),
          coalesce((p ->> 'join_invite')::boolean, true),
          coalesce((p ->> 'join_link')::boolean, true),
          me)
  returning id into new_id;
  insert into public.company_members (company_id, user_id, role, is_main)
  values (new_id, me, 'leader', not exists (select 1 from public.company_members where user_id = me and is_main));
  return s;
end;
$$;

-- Officers edit the card; only the leader changes visibility, joining modes, limit and competition.
create or replace function public.update_company(p_company uuid, p jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.company_role := public.company_role_of(p_company);
  c public.companies;
  n int;
begin
  if r is null or r not in ('leader', 'officer') then
    raise exception 'forbidden';
  end if;
  if r <> 'leader' and (p ?| array['is_public', 'join_open', 'join_invite', 'join_link', 'member_limit', 'competitive']) then
    raise exception 'not_leader';
  end if;
  select * into c from public.companies where id = p_company for update;
  if p ? 'name' and char_length(btrim(coalesce(p ->> 'name', ''))) not between 2 and 60 then
    raise exception 'bad_name';
  end if;
  n := coalesce((p ->> 'member_limit')::int, c.member_limit);
  if n < 2 or n > c.limit_ceiling then
    raise exception 'bad_limit';
  end if;
  update public.companies set
    name        = case when p ? 'name' then btrim(p ->> 'name') else name end,
    motto       = case when p ? 'motto' then left(btrim(coalesce(p ->> 'motto', '')), 120) else motto end,
    description = case when p ? 'description' then left(btrim(coalesce(p ->> 'description', '')), 1000) else description end,
    city        = case when p ? 'city' then nullif(left(btrim(coalesce(p ->> 'city', '')), 80), '') else city end,
    country     = case when p ? 'country' then (case when coalesce(p ->> 'country', '') ~ '^[A-Z]{2}$' then p ->> 'country' end) else country end,
    is_online   = coalesce((p ->> 'is_online')::boolean, is_online),
    languages   = case when p ? 'languages' then public.company_clean_langs(array(select jsonb_array_elements_text(case when jsonb_typeof(p -> 'languages') = 'array' then p -> 'languages' else '[]' end))) else languages end,
    games       = case when p ? 'games' then left(btrim(coalesce(p ->> 'games', '')), 200) else games end,
    crest       = case when p ? 'crest' then public.company_clean_crest(p -> 'crest') else crest end,
    is_public   = coalesce((p ->> 'is_public')::boolean, is_public),
    join_open   = coalesce((p ->> 'join_open')::boolean, join_open),
    join_invite = coalesce((p ->> 'join_invite')::boolean, join_invite),
    join_link   = coalesce((p ->> 'join_link')::boolean, join_link),
    member_limit = n,
    competitive = coalesce((p ->> 'competitive')::boolean, competitive)
  where id = p_company;
  if coalesce((p ->> 'join_link')::boolean, true) = false then
    delete from public.company_links where company_id = p_company;
  end if;
end;
$$;

-- An admin raises (or lowers) the ceiling; the limit follows when it is above.
create or replace function public.admin_set_company_ceiling(p_company uuid, p_ceiling int)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  if p_ceiling is null or p_ceiling not between 2 and 1000 then
    raise exception 'bad_limit';
  end if;
  update public.companies set limit_ceiling = p_ceiling, member_limit = least(member_limit, p_ceiling) where id = p_company;
end;
$$;

create or replace function public.dissolve_company(p_company uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.companies;
  u uuid;
begin
  if public.company_role_of(p_company) is distinct from 'leader' then
    raise exception 'not_leader';
  end if;
  select * into c from public.companies where id = p_company;
  for u in select user_id from public.company_members where company_id = p_company and user_id <> auth.uid() loop
    perform public.notify(u, 'company_dissolved', jsonb_build_object('company', c.name));
  end loop;
  -- Main flags move to the members' other Companies
  update public.company_members cm set is_main = true
   where (cm.company_id, cm.user_id) in (
     select distinct on (o.user_id) o.company_id, o.user_id
       from public.company_members o
       join public.company_members gone on gone.user_id = o.user_id and gone.company_id = p_company and gone.is_main
      where o.company_id <> p_company
      order by o.user_id, o.joined_at);
  delete from public.companies where id = p_company;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Joining
-- ---------------------------------------------------------------------------------------------
create or replace function public.join_company(p_company uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (select 1 from public.companies where id = p_company and join_open and not is_hidden) then
    raise exception 'not_open';
  end if;
  perform public.company_add_member(p_company, auth.uid());
end;
$$;

-- Officers turn the link on (a new token each time: the old one stops working), optionally for N days.
create or replace function public.reset_company_link(p_company uuid, p_days int default null)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  tok text := replace(gen_random_uuid()::text, '-', '');
begin
  if not public.is_company_officer(p_company) then
    raise exception 'forbidden';
  end if;
  if not exists (select 1 from public.companies where id = p_company and join_link) then
    raise exception 'link_off';
  end if;
  insert into public.company_links (company_id, token, expires_at)
  values (p_company, tok, case when p_days between 1 and 365 then now() + make_interval(days => p_days) end)
  on conflict (company_id) do update set token = excluded.token, expires_at = excluded.expires_at, created_at = now();
  return tok;
end;
$$;

create or replace function public.join_company_by_link(p_token text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.companies;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;
  select co.* into c from public.company_links l join public.companies co on co.id = l.company_id
   where l.token = p_token and (l.expires_at is null or l.expires_at > now()) and co.join_link and not co.is_hidden;
  if not found then
    raise exception 'bad_link';
  end if;
  if not exists (select 1 from public.company_members where company_id = c.id and user_id = auth.uid()) then
    perform public.company_add_member(c.id, auth.uid());
  end if;
  return c.slug;
end;
$$;

-- What a link leads to, before joining (name and crest only).
create or replace function public.company_link_preview(p_token text)
returns table (slug text, name text, motto text, crest jsonb, city text, is_online boolean, members bigint)
language sql
stable
security definer
set search_path = public
as $$
  select co.slug, co.name, co.motto, co.crest, co.city, co.is_online,
         (select count(*) from public.company_members m where m.company_id = co.id)
    from public.company_links l join public.companies co on co.id = l.company_id
   where l.token = p_token and (l.expires_at is null or l.expires_at > now()) and co.join_link and not co.is_hidden;
$$;

create or replace function public.invite_to_company(p_company uuid, p_handle text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.companies;
  target uuid;
  who text;
begin
  if not public.is_company_officer(p_company) then
    raise exception 'forbidden';
  end if;
  select * into c from public.companies where id = p_company;
  if not c.join_invite then
    raise exception 'invites_off';
  end if;
  select id into target from public.profiles
   where handle = lower(btrim(coalesce(p_handle, ''), ' @')) and deleted_at is null and not is_suspended;
  if target is null then
    raise exception 'no_player';
  end if;
  if exists (select 1 from public.company_members where company_id = p_company and user_id = target) then
    raise exception 'already_member';
  end if;
  if exists (select 1 from public.company_invites where company_id = p_company and user_id = target) then
    return;
  end if;
  if (select count(*) from public.company_invites where invited_by = auth.uid() and created_at > now() - interval '1 day') >= 30 then
    raise exception 'rate_limited';
  end if;
  insert into public.company_invites (company_id, user_id, invited_by) values (p_company, target, auth.uid());
  select display_name into who from public.profiles where id = auth.uid();
  perform public.notify(target, 'company_invite', jsonb_build_object('company', c.name, 'company_slug', c.slug, 'from', who, 'from_id', auth.uid()));
end;
$$;

create or replace function public.answer_company_invite(p_company uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.company_invites where company_id = p_company and user_id = auth.uid()) then
    raise exception 'no_invite';
  end if;
  if coalesce(p_accept, false) then
    perform public.company_add_member(p_company, auth.uid());
  else
    delete from public.company_invites where company_id = p_company and user_id = auth.uid();
  end if;
end;
$$;

create or replace function public.cancel_company_invite(p_company uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_company_officer(p_company) then
    raise exception 'forbidden';
  end if;
  delete from public.company_invites where company_id = p_company and user_id = p_user;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Members and roles
-- ---------------------------------------------------------------------------------------------
create or replace function public.leave_company(p_company uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.company_drop_member(p_company, auth.uid());
end;
$$;

-- Officers remove members and recruits; the leader removes anyone but themselves.
create or replace function public.remove_company_member(p_company uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  mine public.company_role := public.company_role_of(p_company);
  theirs public.company_role := public.company_role_of(p_company, p_user);
  c public.companies;
begin
  if theirs is null then
    raise exception 'not_member';
  end if;
  if p_user = auth.uid() or mine is null
     or not (mine = 'leader' or (mine = 'officer' and theirs in ('member', 'recruit'))) then
    raise exception 'forbidden';
  end if;
  perform public.company_drop_member(p_company, p_user);
  select * into c from public.companies where id = p_company;
  perform public.notify(p_user, 'company_removed', jsonb_build_object('company', c.name));
end;
$$;

-- The leader names officers, members and recruits, or hands over (p_role = 'leader': they become an officer).
-- Officers move players between member and recruit.
create or replace function public.set_company_role(p_company uuid, p_user uuid, p_role public.company_role)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  mine public.company_role := public.company_role_of(p_company);
  theirs public.company_role := public.company_role_of(p_company, p_user);
  c public.companies;
begin
  if theirs is null then
    raise exception 'not_member';
  end if;
  if p_user = auth.uid() or mine is null then
    raise exception 'forbidden';
  end if;
  if mine = 'officer' then
    if theirs not in ('member', 'recruit') or p_role not in ('member', 'recruit') then
      raise exception 'forbidden';
    end if;
  elsif mine <> 'leader' then
    raise exception 'forbidden';
  end if;
  if theirs = p_role then
    return;
  end if;
  select * into c from public.companies where id = p_company;
  if p_role = 'leader' then
    update public.company_members set role = 'officer' where company_id = p_company and user_id = auth.uid();
    update public.company_members set role = 'leader' where company_id = p_company and user_id = p_user;
    perform public.notify(p_user, 'company_leader', jsonb_build_object('company', c.name, 'company_slug', c.slug));
  else
    update public.company_members set role = p_role where company_id = p_company and user_id = p_user;
    perform public.notify(p_user, 'company_role', jsonb_build_object('company', c.name, 'company_slug', c.slug, 'role', p_role::text));
  end if;
end;
$$;

create or replace function public.set_main_company(p_company uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_company_member(p_company) then
    raise exception 'not_member';
  end if;
  update public.company_members set is_main = false where user_id = auth.uid() and is_main and company_id <> p_company;
  update public.company_members set is_main = true where user_id = auth.uid() and company_id = p_company;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Lists
-- ---------------------------------------------------------------------------------------------
create or replace function public.search_companies(p_query text default null, p_city text default null, p_lang text default null, p_online boolean default null)
returns table (id uuid, slug text, name text, motto text, crest jsonb, city text, country text, is_online boolean,
               languages text[], games text, is_public boolean, join_open boolean, members bigint, member_limit int)
language sql
stable
security definer
set search_path = public
as $$
  select c.id, c.slug, c.name, c.motto, c.crest, c.city, c.country, c.is_online, c.languages, c.games, c.is_public, c.join_open,
         (select count(*) from public.company_members m where m.company_id = c.id), c.member_limit
    from public.companies c
   where not c.is_hidden
     and (coalesce(btrim(p_query), '') = '' or c.name ilike '%' || btrim(p_query) || '%' or c.games ilike '%' || btrim(p_query) || '%')
     and (coalesce(btrim(p_city), '') = '' or c.city ilike '%' || btrim(p_city) || '%')
     and (coalesce(p_lang, '') = '' or p_lang = any (c.languages))
     and (p_online is null or c.is_online = p_online)
   order by (select count(*) from public.company_members m where m.company_id = c.id) desc, c.created_at desc
   limit 60;
$$;

create or replace function public.my_companies()
returns table (id uuid, slug text, name text, motto text, crest jsonb, city text, is_online boolean, role text, is_main boolean, members bigint)
language sql
stable
security definer
set search_path = public
as $$
  select c.id, c.slug, c.name, c.motto, c.crest, c.city, c.is_online, m.role::text, m.is_main,
         (select count(*) from public.company_members x where x.company_id = c.id)
    from public.company_members m join public.companies c on c.id = m.company_id
   where m.user_id = auth.uid()
   order by m.is_main desc, m.joined_at;
$$;

create or replace function public.my_company_invites()
returns table (company_id uuid, slug text, name text, crest jsonb, invited_by text, created_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select c.id, c.slug, c.name, c.crest, p.display_name, i.created_at
    from public.company_invites i
    join public.companies c on c.id = i.company_id
    left join public.profiles p on p.id = i.invited_by
   where i.user_id = auth.uid()
   order by i.created_at desc;
$$;

-- One Company page: card, my role, counts; the members when visible.
create or replace function public.company_page(p_slug text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  c public.companies;
  r public.company_role;
  invited boolean;
begin
  select * into c from public.companies where slug = p_slug;
  if not found or not public.company_is_listed(c.id) then
    return null;
  end if;
  r := public.company_role_of(c.id);
  invited := exists (select 1 from public.company_invites where company_id = c.id and user_id = auth.uid());
  return to_jsonb(c) - 'created_by'
    || jsonb_build_object(
         'my_role', r,
         'invited', invited,
         'members_count', (select count(*) from public.company_members where company_id = c.id),
         'can_see', public.company_content_visible(c.id),
         'members', case when public.company_content_visible(c.id) then coalesce((
            select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'display_name', p.display_name, 'handle', p.handle,
                                                'role', m.role, 'joined_at', m.joined_at) order by
                     array_position(array['leader', 'officer', 'member', 'recruit']::public.company_role[], m.role), m.joined_at)
              from public.company_members m join public.profiles p on p.id = m.user_id
             where m.company_id = c.id), '[]') end,
         'invites', case when r in ('leader', 'officer') then coalesce((
            select jsonb_agg(jsonb_build_object('user_id', i.user_id, 'display_name', p.display_name, 'handle', p.handle) order by i.created_at)
              from public.company_invites i join public.profiles p on p.id = i.user_id
             where i.company_id = c.id), '[]') end,
         'next_event', case when r is not null then (
            select jsonb_build_object('id', e.id, 'title', e.title, 'starts_at', e.starts_at)
              from public.company_events e where e.company_id = c.id and e.ends_at > now() order by e.starts_at limit 1) end);
end;
$$;

-- Companies shown on a player's page: the ones the viewer may see.
create or replace function public.player_companies(p_user uuid)
returns table (slug text, name text, crest jsonb, role text, is_main boolean)
language sql
stable
security definer
set search_path = public
as $$
  select c.slug, c.name, c.crest, m.role::text, m.is_main
    from public.company_members m join public.companies c on c.id = m.company_id
   where m.user_id = p_user and public.company_content_visible(c.id) and (not c.is_hidden or public.is_admin())
   order by m.is_main desc, m.joined_at;
$$;

-- ---------------------------------------------------------------------------------------------
-- Chat and announcements
-- ---------------------------------------------------------------------------------------------
create or replace function public.post_company_message(p_company uuid, p_body text, p_announce boolean default false)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  body text := btrim(coalesce(p_body, ''));
  new_id uuid;
  c public.companies;
  who text;
  u uuid;
begin
  if not public.is_company_member(p_company) then
    raise exception 'not_member';
  end if;
  if coalesce(p_announce, false) and not public.is_company_officer(p_company) then
    raise exception 'forbidden';
  end if;
  if char_length(body) not between 1 and 1000 then
    raise exception 'bad_comment';
  end if;
  if (select count(*) from public.company_messages where sender_id = auth.uid() and created_at > now() - interval '10 minutes') >= 30 then
    raise exception 'rate_limited';
  end if;
  insert into public.company_messages (company_id, sender_id, body, is_announcement)
  values (p_company, auth.uid(), body, coalesce(p_announce, false))
  returning id into new_id;
  if coalesce(p_announce, false) then
    select * into c from public.companies where id = p_company;
    select display_name into who from public.profiles where id = auth.uid();
    for u in select user_id from public.company_members where company_id = p_company and user_id <> auth.uid() loop
      perform public.notify(u, 'company_announcement', jsonb_build_object('company', c.name, 'company_slug', c.slug, 'from', who, 'from_id', auth.uid()));
    end loop;
  end if;
  return new_id;
end;
$$;

-- Officers turn a message into an announcement or back (no new notification when unpinned).
create or replace function public.pin_company_message(p_message uuid, p_pinned boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  m public.company_messages;
begin
  select * into m from public.company_messages where id = p_message;
  if not found or not public.is_company_officer(m.company_id) then
    raise exception 'forbidden';
  end if;
  update public.company_messages set is_announcement = coalesce(p_pinned, false) where id = p_message;
end;
$$;

create or replace function public.delete_company_message(p_message uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.company_messages m
   where m.id = p_message
     and (m.sender_id = auth.uid() or public.is_company_officer(m.company_id) or public.is_admin());
  if not found then
    raise exception 'forbidden';
  end if;
end;
$$;

-- Reports: three distinct reporters hide a message or a Company until an admin looks at it.
create or replace function public.report_company_content(p_type text, p_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;
  if p_type = 'company_message' then
    if not exists (select 1 from public.company_messages m where m.id = p_id and public.is_company_member(m.company_id)) then
      raise exception 'no_comment';
    end if;
  elsif p_type = 'company' then
    if not exists (select 1 from public.companies where id = p_id) then
      raise exception 'no_company';
    end if;
  else
    raise exception 'bad_type';
  end if;
  if exists (select 1 from public.reports where reporter_id = auth.uid() and target_type::text = p_type and target_id = p_id::text) then
    return;
  end if;
  insert into public.reports (reporter_id, target_type, target_id, reason)
  values (auth.uid(), p_type::public.report_target, p_id::text, left(btrim(coalesce(p_reason, '')), 500));
  if (select count(distinct reporter_id) from public.reports where target_type::text = p_type and target_id = p_id::text and status = 'open') >= 3 then
    if p_type = 'company_message' then
      update public.company_messages set is_hidden = true where id = p_id;
    else
      update public.companies set is_hidden = true where id = p_id;
    end if;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Calendar
-- ---------------------------------------------------------------------------------------------
create or replace function public.save_company_event(p_company uuid, p_id uuid, p jsonb)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  st timestamptz;
  en timestamptz;
  ttl text := btrim(coalesce(p ->> 'title', ''));
  new_id uuid := p_id;
  c public.companies;
  who text;
  u uuid;
begin
  if not public.is_company_officer(p_company) then
    raise exception 'forbidden';
  end if;
  begin
    st := (p ->> 'starts_at')::timestamptz;
    en := coalesce((p ->> 'ends_at')::timestamptz, st + interval '3 hours');
  exception when others then
    raise exception 'bad_dates';
  end;
  if st is null or en <= st or en > st + interval '7 days' then
    raise exception 'bad_dates';
  end if;
  if char_length(ttl) not between 2 and 120 then
    raise exception 'bad_name';
  end if;
  if p_id is null then
    if st < now() - interval '1 hour' then
      raise exception 'starts_in_past';
    end if;
    if (select count(*) from public.company_events where company_id = p_company and created_at > now() - interval '1 day') >= 20 then
      raise exception 'rate_limited';
    end if;
    insert into public.company_events (company_id, title, starts_at, ends_at, place, details, created_by)
    values (p_company, ttl, st, en, left(btrim(coalesce(p ->> 'place', '')), 200), left(btrim(coalesce(p ->> 'details', '')), 1000), auth.uid())
    returning id into new_id;
    select * into c from public.companies where id = p_company;
    select display_name into who from public.profiles where id = auth.uid();
    for u in select user_id from public.company_members where company_id = p_company and user_id <> auth.uid() loop
      perform public.notify(u, 'company_event', jsonb_build_object('company', c.name, 'company_slug', c.slug, 'game', ttl,
                                                                  'starts_at', st, 'from', who, 'from_id', auth.uid()));
    end loop;
  else
    update public.company_events
       set title = ttl, starts_at = st, ends_at = en,
           place = left(btrim(coalesce(p ->> 'place', '')), 200), details = left(btrim(coalesce(p ->> 'details', '')), 1000)
     where id = p_id and company_id = p_company;
    if not found then
      raise exception 'no_event';
    end if;
  end if;
  return new_id;
end;
$$;

create or replace function public.delete_company_event(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.company_events e where e.id = p_id and public.is_company_officer(e.company_id);
  if not found then
    raise exception 'forbidden';
  end if;
end;
$$;

create or replace function public.answer_company_event(p_id uuid, p_answer text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  e public.company_events;
begin
  select * into e from public.company_events where id = p_id;
  if not found or not public.is_company_member(e.company_id) then
    raise exception 'not_member';
  end if;
  if e.ends_at < now() then
    raise exception 'event_over';
  end if;
  if p_answer is null then
    delete from public.company_event_answers where event_id = p_id and user_id = auth.uid();
  elsif p_answer in ('yes', 'maybe', 'no') then
    insert into public.company_event_answers (event_id, user_id, answer) values (p_id, auth.uid(), p_answer)
    on conflict (event_id, user_id) do update set answer = excluded.answer;
  else
    raise exception 'bad_answer';
  end if;
end;
$$;

create or replace function public.company_calendar(p_company uuid, p_past boolean default false)
returns table (id uuid, title text, starts_at timestamptz, ends_at timestamptz, place text, details text,
               yes bigint, maybe bigint, my_answer text, going text[])
language sql
stable
security definer
set search_path = public
as $$
  select e.id, e.title, e.starts_at, e.ends_at, e.place, e.details,
         (select count(*) from public.company_event_answers a where a.event_id = e.id and a.answer = 'yes'),
         (select count(*) from public.company_event_answers a where a.event_id = e.id and a.answer = 'maybe'),
         (select a.answer from public.company_event_answers a where a.event_id = e.id and a.user_id = auth.uid()),
         array(select p.display_name from public.company_event_answers a join public.profiles p on p.id = a.user_id
                where a.event_id = e.id and a.answer = 'yes' order by p.display_name)
    from public.company_events e
   where e.company_id = p_company
     and public.is_company_member(p_company)
     and (case when p_past then e.ends_at <= now() and e.ends_at > now() - interval '180 days' else e.ends_at > now() end)
   order by case when p_past then null else e.starts_at end, e.starts_at desc
   limit 100;
$$;

-- ---------------------------------------------------------------------------------------------
-- Rights
-- ---------------------------------------------------------------------------------------------
revoke execute on function
  public.create_company(jsonb), public.update_company(uuid, jsonb), public.admin_set_company_ceiling(uuid, int),
  public.dissolve_company(uuid), public.join_company(uuid), public.reset_company_link(uuid, int),
  public.join_company_by_link(text), public.invite_to_company(uuid, text), public.answer_company_invite(uuid, boolean),
  public.cancel_company_invite(uuid, uuid), public.leave_company(uuid), public.remove_company_member(uuid, uuid),
  public.set_company_role(uuid, uuid, public.company_role), public.set_main_company(uuid),
  public.my_companies(), public.my_company_invites(),
  public.post_company_message(uuid, text, boolean), public.pin_company_message(uuid, boolean), public.delete_company_message(uuid),
  public.report_company_content(text, uuid, text), public.save_company_event(uuid, uuid, jsonb), public.delete_company_event(uuid),
  public.answer_company_event(uuid, text), public.company_calendar(uuid, boolean)
from public, anon;
grant execute on function
  public.create_company(jsonb), public.update_company(uuid, jsonb), public.admin_set_company_ceiling(uuid, int),
  public.dissolve_company(uuid), public.join_company(uuid), public.reset_company_link(uuid, int),
  public.join_company_by_link(text), public.invite_to_company(uuid, text), public.answer_company_invite(uuid, boolean),
  public.cancel_company_invite(uuid, uuid), public.leave_company(uuid), public.remove_company_member(uuid, uuid),
  public.set_company_role(uuid, uuid, public.company_role), public.set_main_company(uuid),
  public.my_companies(), public.my_company_invites(),
  public.post_company_message(uuid, text, boolean), public.pin_company_message(uuid, boolean), public.delete_company_message(uuid),
  public.report_company_content(text, uuid, text), public.save_company_event(uuid, uuid, jsonb), public.delete_company_event(uuid),
  public.answer_company_event(uuid, text), public.company_calendar(uuid, boolean)
to authenticated;
-- Readable by visitors: the list, a page, a link preview, a player's Companies.
revoke execute on function public.search_companies(text, text, text, boolean), public.company_page(text),
  public.company_link_preview(text), public.player_companies(uuid) from public;
grant execute on function public.search_companies(text, text, text, boolean), public.company_page(text),
  public.company_link_preview(text), public.player_companies(uuid) to anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Moderation: reports labels, content list and hide / restore for Companies and their messages
-- ---------------------------------------------------------------------------------------------
create or replace function public.admin_reports(p_status text default 'open')
returns table (id uuid, created_at timestamptz, status text, target_type text, target_id text, reason text,
               reporter_handle text, target_label text, owner_id uuid, owner_handle text, target_hidden boolean, same_target bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select r.id, r.created_at, r.status::text, r.target_type::text, r.target_id, r.reason, rp.handle,
           case r.target_type::text
             when 'swap' then (select s.title from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.title from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.title from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then (select p.display_name from public.profiles p where p.id::text = r.target_id)
             when 'photo' then (select gi.title from public.gallery_items gi where gi.id::text = r.target_id)
             when 'comment' then (select left(gc.body, 120) from public.game_comments gc where gc.id::text = r.target_id)
             when 'company' then (select co.name from public.companies co where co.id::text = r.target_id)
             when 'company_message' then (select left(cm.body, 120) from public.company_messages cm where cm.id::text = r.target_id)
             else r.target_id end,
           o.id, o.handle,
           case r.target_type::text
             when 'swap' then (select s.is_hidden from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.is_hidden from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.is_hidden from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then (select not p.is_public from public.profiles p where p.id::text = r.target_id)
             when 'photo' then (select not gi.is_public from public.gallery_items gi where gi.id::text = r.target_id)
             when 'comment' then (select gc.is_hidden from public.game_comments gc where gc.id::text = r.target_id)
             when 'company' then (select co.is_hidden from public.companies co where co.id::text = r.target_id)
             when 'company_message' then (select cm.is_hidden from public.company_messages cm where cm.id::text = r.target_id)
             else null end,
           (select count(*) from public.reports x where x.target_type = r.target_type and x.target_id = r.target_id)
      from public.reports r
      join public.profiles rp on rp.id = r.reporter_id
      left join public.profiles o on o.id = case r.target_type::text
             when 'swap' then (select s.user_id from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.user_id from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.user_id from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then r.target_id::uuid
             when 'photo' then (select gi.owner_id from public.gallery_items gi where gi.id::text = r.target_id)
             when 'comment' then (select gc.author_id from public.game_comments gc where gc.id::text = r.target_id)
             when 'company' then (select m.user_id from public.company_members m where m.company_id::text = r.target_id and m.role = 'leader')
             when 'company_message' then (select cm.sender_id from public.company_messages cm where cm.id::text = r.target_id)
             else null end
     where p_status = 'all' or r.status::text = p_status
     order by r.created_at desc
     limit 200;
end;
$$;

create or replace function public.admin_content(p_type text, p_limit int default 50)
returns table (id text, created_at timestamptz, label text, owner_handle text, hidden boolean, link text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  if p_type = 'swap' then
    return query select s.id::text, s.created_at, s.title, p.handle, s.is_hidden, '/play/swap'::text
      from public.swap_posts s join public.profiles p on p.id = s.user_id order by s.created_at desc limit p_limit;
  elsif p_type = 'challenge' then
    return query select c.id::text, c.created_at, c.title, p.handle, c.is_hidden, '/paint/challenges'::text
      from public.challenge_entries c join public.profiles p on p.id = c.user_id order by c.created_at desc limit p_limit;
  elsif p_type = 'tournament' then
    return query select t.id::text, t.created_at, t.name, p.handle, t.is_hidden, '/play/t/' || t.slug
      from public.tournaments t join public.profiles p on p.id = t.organiser_id order by t.created_at desc limit p_limit;
  elsif p_type = 'game' then
    return query select g.id::text, g.created_at, g.game_system || ' - ' || g.city, p.handle, g.status = 'cancelled', '/play/game/' || g.id
      from public.games g join public.profiles p on p.id = g.host_id order by g.created_at desc limit p_limit;
  elsif p_type = 'lfg' then
    return query select l.id::text, l.created_at, l.game_system, p.handle, not l.is_open, '/play/quick?view=lfg'::text
      from public.lfg_posts l join public.profiles p on p.id = l.author_id order by l.created_at desc limit p_limit;
  elsif p_type = 'company' then
    return query select co.id::text, co.created_at,
                        co.name || ' (' || (select count(*) from public.company_members m where m.company_id = co.id) || ' / ' || co.limit_ceiling || ')',
                        p.handle, co.is_hidden, '/play/c/' || co.slug
      from public.companies co
      left join public.company_members l on l.company_id = co.id and l.role = 'leader'
      left join public.profiles p on p.id = l.user_id
     order by co.created_at desc limit p_limit;
  else
    raise exception 'bad_type';
  end if;
end;
$$;

create or replace function public.admin_moderate(p_type text, p_id text, p_hidden boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  case p_type
    when 'swap' then update public.swap_posts set is_hidden = p_hidden where id::text = p_id;
    when 'challenge' then update public.challenge_entries set is_hidden = p_hidden where id::text = p_id;
    when 'entry' then update public.contest_entries set is_hidden = p_hidden where id::text = p_id;
    when 'tournament' then update public.tournaments set is_hidden = p_hidden where id::text = p_id;
    when 'game' then update public.games set status = case when p_hidden then 'cancelled' else 'open' end::public.game_status where id::text = p_id;
    when 'lfg' then update public.lfg_posts set is_open = not p_hidden where id::text = p_id;
    when 'profile' then update public.profiles set is_public = not p_hidden where id::text = p_id;
    when 'photo' then update public.gallery_items set is_public = not p_hidden where id::text = p_id;
    when 'comment' then update public.game_comments set is_hidden = p_hidden where id::text = p_id;
    when 'company' then update public.companies set is_hidden = p_hidden where id::text = p_id;
    when 'company_message' then update public.company_messages set is_hidden = p_hidden where id::text = p_id;
    else raise exception 'bad_type';
  end case;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Account deletion: Companies are left (with the handover), invitations and answers go,
-- chat messages stay under "Deleted player" (owner decision 2026-11-27).
-- ---------------------------------------------------------------------------------------------
create or replace function public.companies_forget(p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  x record;
begin
  for x in select company_id from public.company_members where user_id = p_user loop
    perform public.company_drop_member(x.company_id, p_user);
  end loop;
  delete from public.company_invites where user_id = p_user;
  delete from public.company_event_answers where user_id = p_user;
end;
$$;
revoke execute on function public.companies_forget(uuid) from public, anon, authenticated;

-- Same as migration 28, plus the Companies (see companies_forget).
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public, auth, storage
as $$
declare
  me uuid := auth.uid();
  my_name text;
  x record;
  heir uuid;
begin
  if me is null then
    raise exception 'not_authenticated';
  end if;
  select display_name into my_name from public.profiles where id = me and deleted_at is null for update;
  if not found then
    raise exception 'not_found';
  end if;
  if public.is_admin() then
    raise exception 'admin_account';
  end if;
  -- The app asks for the password again just before; a session left open somewhere is not enough.
  if not exists (select 1 from auth.users u where u.id = me and u.last_sign_in_at > now() - interval '15 minutes') then
    raise exception 'recent_sign_in';
  end if;
  -- Players are waiting for their results: the organiser finishes the event first.
  if exists (select 1 from public.tournaments t where t.organiser_id = me and t.status = 'in_progress') then
    raise exception 'tournament_running';
  end if;
  -- Files go through the Storage API (Supabase refuses SQL deletes there).
  if exists (select 1 from storage.objects o where o.owner = me) then
    raise exception 'files_left';
  end if;

  -- Other players' notices about me (they carry my name)
  delete from public.notifications n
   where n.user_id = me
      or n.payload ->> 'from_id' = me::text
      or n.payload ->> 'mentorship_id' in (select s.id::text from public.mentorships s where me in (s.mentor_id, s.mentee_id))
      or (n.payload ->> 'from' = my_name
          and (n.kind in ('game_deleted', 'suggestion')
               or n.payload ->> 'game_id' in (select p.game_id::text from public.game_players p where p.player_id = me
                                              union select g.id::text from public.games g where g.host_id = me)));
  -- From here on, the notices sent to other players (a cancelled game) carry no name.
  update public.profiles set display_name = 'Deleted player' where id = me;

  -- Games: the ones nobody else plays in, and the upcoming ones I host, disappear; I leave the others.
  for x in
    select g.id from public.games g
     where g.host_id = me
       and (g.starts_at > now()
            or (not exists (select 1 from public.game_players p
                             where p.game_id = g.id and p.player_id <> me and p.status = 'accepted')
                and not exists (select 1 from public.game_results r where r.game_id = g.id and r.player_id <> me)))
  loop
    perform public.delete_game(x.id);
  end loop;
  for x in
    select p.game_id from public.game_players p join public.games g on g.id = p.game_id
     where p.player_id = me and g.starts_at > now() and p.status in ('pending', 'accepted')
  loop
    perform public.leave_game(x.game_id);
  end loop;
  delete from public.game_players where player_id = me and status <> 'accepted';
  update public.game_players set message = null where player_id = me;
  delete from public.game_private where game_id in (select id from public.games where host_id = me);
  update public.games set note = null, area = null where host_id = me;
  update public.game_reports set summary = null where reported_by = me;
  -- My report photos are gone by now: drop their paths, keep the other players' photos.
  update public.game_reports r
     set photos = array(select f from unnest(r.photos) f
                         where exists (select 1 from storage.objects o where o.bucket_id = 'reports' and o.name = f))
   where cardinality(r.photos) > 0
     and exists (select 1 from public.game_players p where p.game_id = r.game_id and p.player_id = me);
  delete from public.game_messages where sender_id = me;
  delete from public.game_comments where author_id = me;

  -- Tournaments: drafts disappear, published ones are cancelled, finished ones stay.
  delete from public.tournaments where organiser_id = me and status = 'draft';
  update public.tournaments set status = 'cancelled', twitch_channel = null where organiser_id = me and status = 'published';
  for x in
    select r.tournament_id, t.status from public.registrations r join public.tournaments t on t.id = r.tournament_id
     where r.user_id = me and r.status in ('registered', 'waitlist') and t.status in ('published', 'in_progress')
  loop
    if x.status = 'published' then
      perform public.withdraw_from_tournament(x.tournament_id);
    else
      update public.registrations set status = 'dropped' where tournament_id = x.tournament_id and user_id = me;
    end if;
  end loop;
  delete from public.army_lists where registration_id in (select id from public.registrations where user_id = me);
  delete from public.contest_entries where user_id = me;
  delete from public.challenge_entries where user_id = me;
  delete from public.challenge_likes where user_id = me;
  delete from public.match_predictions where user_id = me;

  -- Leagues and campaigns: the oldest other member takes over, or they disappear with me.
  for x in select id from public.leagues where organiser_id = me loop
    select m.player_id into heir from public.league_members m
     where m.league_id = x.id and m.player_id <> me order by m.joined_at limit 1;
    if heir is null then
      delete from public.leagues where id = x.id;
    else
      update public.leagues set organiser_id = heir where id = x.id;
    end if;
  end loop;
  delete from public.league_members m using public.leagues l
   where l.id = m.league_id and m.player_id = me and l.ends_on >= current_date;
  for x in select id from public.campaigns where master_id = me loop
    select m.user_id into heir from public.campaign_members m
     where m.campaign_id = x.id and m.user_id <> me order by m.joined_at limit 1;
    if heir is null then
      delete from public.campaigns where id = x.id;
    else
      update public.campaigns set master_id = heir where id = x.id;
    end if;
  end loop;
  delete from public.campaign_decks where owner_id = me;
  delete from public.campaign_members where user_id = me;

  -- Companies: handover when I lead, invitations and answers go, my messages stay (anonymised by the profile below)
  perform public.companies_forget(me);

  -- What is mine alone
  delete from public.decks where owner_id = me;
  delete from public.pile_armies where owner_id = me;
  delete from public.gallery_items where owner_id = me;
  delete from public.schemes where owner_id = me;
  delete from public.direct_messages where me in (sender_id, recipient_id);
  delete from public.mentorships where me in (mentor_id, mentee_id);
  delete from public.mentor_profiles where user_id = me;
  delete from public.lfg_posts where author_id = me;
  delete from public.swap_posts where user_id = me;
  delete from public.player_ratings where player_id = me;
  delete from public.active_days where user_id = me;
  delete from public.store_staff where user_id = me;
  delete from public.reports where reporter_id = me;
  delete from public.events where user_id = me;
  update public.bug_reports set user_id = null, contact = null, context = '{}', photos = '{}' where user_id = me;
  update public.suggestions set user_id = null, contact = null where user_id = me;
  update public.translation_suggestions set user_id = null where user_id = me;

  -- The name left on shared games and journals; suspended: an open session cannot post any more.
  update public.profiles
     set handle = 'deleted_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12),
         display_name = 'Deleted player', avatar_path = null, home_city = null, home_location = null,
         factions = '{}', preferred_lang = 'en', is_public = false,
         is_suspended = true, suspended_reason = null, deleted_at = now()
   where id = me;

  -- Sign-in data
  delete from auth.identities where user_id = me;
  delete from auth.sessions where user_id = me;
  delete from auth.one_time_tokens where user_id = me;
  delete from auth.mfa_factors where user_id = me;
  update auth.users
     set email = 'deleted-' || me::text || '@deleted.invalid', phone = null, encrypted_password = '',
         raw_user_meta_data = '{}', raw_app_meta_data = '{}', banned_until = now() + interval '100 years',
         confirmation_token = '', recovery_token = '', email_change = '', email_change_token_new = '',
         email_change_token_current = '', phone_change = '', phone_change_token = '', reauthentication_token = ''
   where id = me;
end;
$$;
revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

$setup_20261127000029_companies$;
    raise notice 'applied: 20261127000029_companies.sql';
  else
    raise notice 'already there, skipped: 20261127000029_companies.sql';
  end if;
end $guard$;
